from datetime import datetime
from typing import Dict, List, Optional, Tuple

class Scheduler:
    def __init__(self) -> None:
        # Store appointments as a list of tuples: (id, patient, doctor, start, end)
        self._appointments: List[Tuple[int, str, str, datetime, datetime]] = []
        # Track next appointment ID
        self._next_id: int = 1
        # Track patient's upcoming appointments (only one allowed)
        self._patient_appointments: Dict[str, List[int]] = {}

    def book(self, patient: str, doctor: str, start: datetime, end: datetime,
             now: datetime) -> int:
        # Requirement 1: Booking an appointment that starts before `now` raises ValueError
        if start < now:
            raise ValueError("Appointment cannot start before current time")

        # Requirement 2: Booking an appointment that overlaps another appointment of the same doctor
        for appt_id, _, appt_doctor, appt_start, appt_end in self._appointments:
            if appt_doctor == doctor:
                # Check for overlap: two intervals [a,b] and [c,d] overlap if a < d and c < b
                # Since touching is allowed (one ends when another starts), we use strict inequalities
                if start < appt_end and appt_start < end:
                    raise ValueError("Appointment overlaps with existing appointment for this doctor")

        # Requirement 4: A patient can have at most one upcoming appointment
        # Find all upcoming appointments for this patient (start > now)
        upcoming_patient_appts = []
        for appt_id, appt_patient, _, appt_start, _ in self._appointments:
            if appt_patient == patient and appt_start > now:
                upcoming_patient_appts.append(appt_id)

        if len(upcoming_patient_appts) >= 1:
            raise ValueError("Patient already has an upcoming appointment")

        # Create new appointment
        appointment_id = self._next_id
        self._next_id += 1

        # Store the appointment
        self._appointments.append((appointment_id, patient, doctor, start, end))

        # Update patient's appointment tracking
        if patient not in self._patient_appointments:
            self._patient_appointments[patient] = []
        self._patient_appointments[patient].append(appointment_id)

        return appointment_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        # Find the appointment to cancel
        appointment_to_cancel = None
        for i, (appt_id, patient, doctor, start, end) in enumerate(self._appointments):
            if appt_id == appointment_id:
                appointment_to_cancel = (i, patient, doctor, start, end)
                break

        if appointment_to_cancel is None:
            return  # Appointment not found, nothing to do

        i, patient, doctor, start, end = appointment_to_cancel

        # Check if appointment is in the past (already started or ended)
        # We can only cancel upcoming appointments (start > now)
        if start <= now:
            # Appointment has already started or ended, but we still remove it
            # The requirement doesn't specify restrictions on canceling past appointments
            pass

        # Remove the appointment
        self._appointments.pop(i)

        # Update patient's appointment tracking
        if patient in self._patient_appointments:
            if appointment_id in self._patient_appointments[patient]:
                self._patient_appointments[patient].remove(appointment_id)
            # Clean up empty lists
            if not self._patient_appointments[patient]:
                del self._patient_appointments[patient]

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        """True if the doctor can be booked between start and end."""
        for _, _, appt_doctor, appt_start, appt_end in self._appointments:
            if appt_doctor == doctor:
                # Check for overlap: two intervals [a,b] and [c,d] overlap if a < d and c < b
                # Since touching is allowed (one ends when another starts), we use strict inequalities
                if start < appt_end and appt_start < end:
                    return False
        return True
